import{_ as o,o as l,c as i,a2 as r}from"./chunks/framework.QCr1ZR1X.js";const g=JSON.parse('{"title":"第8章 工业互联网核心技术（教师用书）","description":"","frontmatter":{},"headers":[],"relativePath":"teacher/ch8/教师用书-第8章-工业互联网核心技术.md","filePath":"teacher/ch8/教师用书-第8章-工业互联网核心技术.md","lastUpdated":1786967935000}'),a={name:"teacher/ch8/教师用书-第8章-工业互联网核心技术.md"};function d(n,t,e,s,u,h){return l(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="第8章-工业互联网核心技术-教师用书" tabindex="-1">第8章 工业互联网核心技术（教师用书） <a class="header-anchor" href="#第8章-工业互联网核心技术-教师用书" aria-label="Permalink to &quot;第8章 工业互联网核心技术（教师用书）&quot;">​</a></h1><blockquote><p><strong>本章定位</strong>：全书最后一章，站在前七章搭建的技术栈之上，瞭望正在改变工业互联网面貌的核心技术。本章涵盖5G、AI、数字孪生、区块链、工业安全五大技术方向，并安排AI辅助编程实践，旨在开拓学生视野、培养创新思维和安全意识，同时为全书收尾。 <strong>课时安排</strong>：10课时（理论6 + 实践4） <strong>学情分析</strong>：学生已掌握前面七章的实用技术（TCP/IP、Modbus、Node-RED、边缘计算、Docker、MQTT、Dashboard），但对前沿技术了解不多。本章要通过生动案例让学生理解前沿技术，同时通过实践让学生体验AI编程，激发学习兴趣。需重点强调AI的边界、区块链的客观认知和工业安全的重要性。</p></blockquote><hr><h2 id="一、本章教学目标" tabindex="-1">一、本章教学目标 <a class="header-anchor" href="#一、本章教学目标" aria-label="Permalink to &quot;一、本章教学目标&quot;">​</a></h2><h3 id="知识目标" tabindex="-1">知识目标 <a class="header-anchor" href="#知识目标" aria-label="Permalink to &quot;知识目标&quot;">​</a></h3><ol><li>掌握5G的三大模式（eMBB、uRLLC、mMTC）及适用的工业场景，了解5G RedCap轻量化技术和5G专网三种部署模式，了解5G云化PLC及实际案例（鞍钢、芜湖美的）</li><li>了解AI在工业中的三种主要应用形态（视觉检测、预测性维护、工艺优化）及其边界</li><li>理解数字孪生的三个层次（以虚映实、以虚控实、以虚优实）及其与前面技术的关系，了解数字孪生的起源历史（Grieves 2002, NASA 2010），理解数字孪生与仿真的区别</li><li>了解区块链在工业中的应用方向和实际落地现状，客观认识区块链在工业中的应用局限</li><li>了解工业互联网安全的基本原则和常见威胁</li></ol><h3 id="技能目标" tabindex="-1">技能目标 <a class="header-anchor" href="#技能目标" aria-label="Permalink to &quot;技能目标&quot;">​</a></h3><ol><li>能使用VS Code和AI辅助编程工具（如DeepSeek、通义千问、Cursor）编写简单的工业物联网代码</li><li>能识别工业场景中5G三大模式的应用场景，能区分5G专网三种部署模式的适用场景</li><li>能设计简单的数字孪生数据采集方案</li></ol><h3 id="素养目标" tabindex="-1">素养目标 <a class="header-anchor" href="#素养目标" aria-label="Permalink to &quot;素养目标&quot;">​</a></h3><ul><li><strong>创新意识</strong>：了解前沿技术在工业中的应用，培养技术创新思维</li><li><strong>安全意识</strong>：理解工业安全的重要性，树立&quot;安全第一&quot;的理念</li><li><strong>工程师伦理</strong>：明确AI在工业中的角色边界，树立负责任的技术态度</li><li><strong>批判性思维</strong>：客观认识区块链等新兴技术在工业中的真实应用现状，不盲从技术炒作</li><li><strong>工匠精神</strong>：追求技术的精益求精，关注细节和可靠性</li></ul><hr><h2 id="二、课时分配与教学安排" tabindex="-1">二、课时分配与教学安排 <a class="header-anchor" href="#二、课时分配与教学安排" aria-label="Permalink to &quot;二、课时分配与教学安排&quot;">​</a></h2><table tabindex="0"><thead><tr><th>课次</th><th>课时</th><th>内容</th><th>教学类型</th><th>重点/难点</th></tr></thead><tbody><tr><td>第1次课</td><td>2h</td><td>8.1 5G与工业互联网</td><td>理论</td><td><strong>重点</strong>：5G三大模式、RedCap、5G专网三种模式、云化PLC；<strong>难点</strong>：云化PLC的理解、5G专网部署模式的选择</td></tr><tr><td>第2次课</td><td>2h</td><td>8.2 人工智能与工业应用 + 8.3 数字孪生</td><td>理论</td><td><strong>重点</strong>：AI三种形态及边界、数字孪生三层及与仿真的区别；<strong>难点</strong>：AI可解释性问题、数字孪生与仿真的本质区别</td></tr><tr><td>第3次课</td><td>2h</td><td>8.4 区块链与工业可信互联 + 8.5 工业安全</td><td>理论</td><td><strong>重点</strong>：区块链应用方向与局限、纵深防御原则；<strong>难点</strong>：客观认识区块链在工业中的真实地位</td></tr><tr><td>第4次课</td><td>2h</td><td>8.6 动手实践：AI辅助编程入门（任务一）</td><td>实践</td><td><strong>重点</strong>：四种AI编程工具形态、VS Code和AI插件安装、AI生成温度监控代码；<strong>难点</strong>：AI代码的理解和调试</td></tr><tr><td>第5次课</td><td>2h</td><td>8.6 动手实践：AI辅助编程入门（任务二+讨论）</td><td>实践</td><td><strong>重点</strong>：AI生成MQTT完整流程；<strong>难点</strong>：AI代码的测试和审核、&quot;谁为后果负责&quot;的伦理讨论</td></tr></tbody></table><hr><h2 id="三、各节教学实施建议" tabindex="-1">三、各节教学实施建议 <a class="header-anchor" href="#三、各节教学实施建议" aria-label="Permalink to &quot;三、各节教学实施建议&quot;">​</a></h2><h3 id="_8-1-5g与工业互联网-理论-2课时" tabindex="-1">8.1 5G与工业互联网（理论，2课时） <a class="header-anchor" href="#_8-1-5g与工业互联网-理论-2课时" aria-label="Permalink to &quot;8.1 5G与工业互联网（理论，2课时）&quot;">​</a></h3><h4 id="教学导入-10分钟" tabindex="-1">教学导入（10分钟） <a class="header-anchor" href="#教学导入-10分钟" aria-label="Permalink to &quot;教学导入（10分钟）&quot;">​</a></h4><ol><li><strong>对比提问</strong>：&quot;你们手机上用4G还是5G？感觉快了多少？5G在工厂里是不是也只是&#39;更快&#39;？&quot;</li><li><strong>引出主题</strong>：5G在工业中的价值不是下载电影更快，而是三种模式服务完全不同的工业场景——而且现在还有了RedCap、5G专网和云化PLC</li></ol><h4 id="知识讲解-60分钟" tabindex="-1">知识讲解（60分钟） <a class="header-anchor" href="#知识讲解-60分钟" aria-label="Permalink to &quot;知识讲解（60分钟）&quot;">​</a></h4><p><strong>第一部分：5G三大模式（20分钟）</strong></p><ol><li>用表格对比eMBB、uRLLC、mMTC的核心指标和适用场景</li><li>每种模式配一个工业案例： <ul><li>eMBB → SMT产线高速视觉检测、AR远程协作</li><li>uRLLC → 宁波舟山港龙门吊远程操控（强调4G 50-100ms延迟 vs 5G毫秒级延迟的差异）</li><li>mMTC → 大型石化厂数万传感器统一接入</li></ul></li><li>讲解RedCap：填补eMBB和mMTC之间的空白——&quot;需要中等速率、低功耗、但又不能太慢&quot;的工业传感器怎么办？引出3GPP R17标准定义的&quot;轻量5G&quot;，工信部2023年发文推进，2024年起规模商用</li></ol><p><strong>第二部分：5G专网三种部署模式（15分钟）</strong></p><ol><li>回顾第3章讲的VPN和专线，引出5G专网作为第三种选择</li><li>对比三种模式： <ul><li>独立专网：物理隔离，安全性最高，成本最高</li><li>混合专网：共享基站、独享核心网用户面，折中方案</li><li>虚拟专网：网络切片，成本最低，隔离性有限</li></ul></li><li>案例：华为松山湖2.6G+4.9G双频段5G独立专网（16个5G应用场景）、宁波舟山港5G独立专网</li></ol><p><strong>第三部分：5G云化PLC（25分钟）</strong></p><ol><li>回顾第4章的OpenPLC——运行在树莓派上的软PLC，控制逻辑和被控设备还在同一个房间</li><li>引出5G云化PLC：PLC的逻辑运行在云端或边缘服务器上，通过5G网络远程控制</li><li>关键问题：为什么以前做不到？——4G延迟50-100ms，WiFi切换断连，只有5G uRLLC + 5G专网才能把端到端延迟压到可接受范围</li><li><strong>鞍钢案例</strong>：鞍山本部厂区和150公里外鲅鱼圈厂区之间部署5G云化PLC，4.9GHz+2.6GHz双频主备链路，毫秒级热备切换，节省至少10名操作人员</li><li><strong>芜湖美的案例</strong>：5G-A+云化PLC试验线，端到端控制延迟低于10ms，可靠性99.999%，获工信部第六届&quot;绽放杯&quot;一等奖</li><li><strong>强调底线</strong>：安全关键逻辑（急停、安全联锁）仍然必须由本地硬件安全PLC执行——5G再快，也不能把&quot;救命&quot;的回路交给网络</li></ol><h4 id="回顾讨论-15分钟" tabindex="-1">回顾讨论（15分钟） <a class="header-anchor" href="#回顾讨论-15分钟" aria-label="Permalink to &quot;回顾讨论（15分钟）&quot;">​</a></h4><ul><li>讨论题1：&quot;5G的三大模式为什么不能只用一种？如果工厂只部署eMBB，会出什么问题？&quot;</li><li>讨论题2：&quot;5G专网和第3章讲的VPN专线有什么区别？什么场景下工厂会选择5G专网？&quot;</li><li>讨论3：&quot;5G云化PLC把PLC从&#39;盒子&#39;变成了&#39;软件&#39;——这和第4章的&#39;边缘计算&#39;是什么关系？&quot;</li></ul><h4 id="常见q-a" tabindex="-1">常见Q&amp;A <a class="header-anchor" href="#常见q-a" aria-label="Permalink to &quot;常见Q&amp;A&quot;">​</a></h4><ul><li><p><strong>Q：5G能完全替代有线吗？</strong> A：不能。5G在带宽和可靠性上已经接近有线水平，但在极端安全关键场景（如急停回路、安全联锁）中，有线连接仍然是不可替代的。5G和有线是互补关系，不是替代关系。教材中也明确强调&quot;安全关键逻辑仍然必须由本地硬件安全PLC执行&quot;。</p></li><li><p><strong>Q：RedCap和4G物联网模块有什么区别？</strong> A：RedCap是5G标准的一部分，继承了5G的网络切片、低时延等能力，4G物联网模块（如NB-IoT）速率更低、时延更大。RedCap填补的是&quot;比mMTC快、比eMBB便宜&quot;的中间地带。</p></li><li><p><strong>Q：5G专网是不是只有大企业才用得起？</strong> A：目前独立专网的部署成本确实较高，适合大型企业。但混合专网和虚拟专网（网络切片）的成本已大幅降低，中型企业也可以考虑。随着5G专网建设规模扩大，成本会进一步下降。</p></li></ul><hr><h3 id="_8-2-人工智能与工业应用-理论-与8-3共2课时" tabindex="-1">8.2 人工智能与工业应用（理论，与8.3共2课时） <a class="header-anchor" href="#_8-2-人工智能与工业应用-理论-与8-3共2课时" aria-label="Permalink to &quot;8.2 人工智能与工业应用（理论，与8.3共2课时）&quot;">​</a></h3><h4 id="教学导入-10分钟-1" tabindex="-1">教学导入（10分钟） <a class="header-anchor" href="#教学导入-10分钟-1" aria-label="Permalink to &quot;教学导入（10分钟）&quot;">​</a></h4><ol><li><strong>互动提问</strong>：&quot;你们在生活中见过哪些AI应用？（比如ChatGPT、抖音推荐、自动驾驶）&quot;</li><li><strong>案例展示</strong>：展示工业AI视觉检测的视频——AI如何快速检查产品缺陷</li><li><strong>引出主题</strong>：AI在工业中的样子和消费互联网完全不同，它是&quot;看、听、算、断&quot;</li></ol><h4 id="知识讲解-30分钟" tabindex="-1">知识讲解（30分钟） <a class="header-anchor" href="#知识讲解-30分钟" aria-label="Permalink to &quot;知识讲解（30分钟）&quot;">​</a></h4><ol><li><strong>工业AI三种形态</strong>：用案例逐一讲解视觉检测、预测性维护、工艺优化 <ul><li>视觉检测：最成熟的落地形态，消费电子、汽车零部件、食品饮料行业广泛使用</li><li>预测性维护：贯穿全书多个章节的案例线索（第2章GE航空发动机、第4章振动频谱）</li><li>工艺优化：反应釜案例——&quot;电流上升7% + 振动50Hz分量增加 + 温度低1.5℃ → 粘度偏高&quot;</li></ul></li><li><strong>AI的边界</strong>：重点强调AI不能做什么——不能替代安全PLC、可解释性问题、最终决策应由人做</li><li><strong>工业视角</strong>：用真实案例说明AI的价值和局限</li><li><strong>课程思政</strong>：工程师伦理——AI是工具，使用者要为结果负责</li></ol><h4 id="回顾讨论-10分钟" tabindex="-1">回顾讨论（10分钟） <a class="header-anchor" href="#回顾讨论-10分钟" aria-label="Permalink to &quot;回顾讨论（10分钟）&quot;">​</a></h4><ul><li>讨论题1：&quot;工业AI三种形态分别对应数据分析的哪个层次（描述性/诊断性/预测性/指导性）？&quot;</li><li>讨论题2：&quot;&#39;可解释性&#39;为什么在工业场景中比在消费场景中更重要？&quot;</li><li>讨论题3：&quot;你能举出一个&#39;AI应该只做辅助、不能做决策&#39;的工业场景吗？&quot;</li></ul><h4 id="常见q-a-1" tabindex="-1">常见Q&amp;A <a class="header-anchor" href="#常见q-a-1" aria-label="Permalink to &quot;常见Q&amp;A&quot;">​</a></h4><ul><li><p><strong>Q：AI视觉检测的准确率能达到100%吗？</strong> A：不能。任何AI模型都有误判的可能——漏检（把缺陷判为正常）和误检（把正常判为缺陷）。工业实践中通常将AI作为初筛，关键产品仍需人工复检。AI的价值是大幅减少人工目检的工作量，而非完全替代。</p></li><li><p><strong>Q：预测性维护和定期维护哪个更划算？</strong> A：取决于设备类型和故障后果。对于高价值、故障后果严重的设备（如风力发电机、航空发动机），预测性维护更划算；对于低价值、故障后果轻微的设备，定期维护可能更经济。两种方式通常是互补的。</p></li></ul><hr><h3 id="_8-3-数字孪生-物理工厂的-数字兄弟-理论-与8-2共2课时" tabindex="-1">8.3 数字孪生：物理工厂的&quot;数字兄弟&quot;（理论，与8.2共2课时） <a class="header-anchor" href="#_8-3-数字孪生-物理工厂的-数字兄弟-理论-与8-2共2课时" aria-label="Permalink to &quot;8.3 数字孪生：物理工厂的&quot;数字兄弟&quot;（理论，与8.2共2课时）&quot;">​</a></h3><h4 id="教学导入-10分钟-2" tabindex="-1">教学导入（10分钟） <a class="header-anchor" href="#教学导入-10分钟-2" aria-label="Permalink to &quot;教学导入（10分钟）&quot;">​</a></h4><ol><li><strong>类比引入</strong>：&quot;你玩过模拟城市或者赛车游戏吗？如果游戏里的城市和真实城市的数据是实时同步的，那会怎样？&quot;</li><li><strong>引出主题</strong>：数字孪生就是让物理工厂在计算机里有了一个&quot;长得一模一样、行为一模一样、状态一模一样&quot;的数字模型</li></ol><h4 id="知识讲解-35分钟" tabindex="-1">知识讲解（35分钟） <a class="header-anchor" href="#知识讲解-35分钟" aria-label="Permalink to &quot;知识讲解（35分钟）&quot;">​</a></h4><p><strong>第一部分：数字孪生的起源（10分钟）</strong></p><ol><li>2002年密歇根大学Michael Grieves教授在PLM课程中提出&quot;镜像空间模型&quot;</li><li>2010年NASA在技术路线图中正式使用&quot;Digital Twin&quot;名称，用于航天器全生命周期管理</li><li>此后西门子、达索、PTC等工业软件巨头纷纷纳入产品体系，数字孪生逐渐成为工业4.0核心概念</li></ol><p><strong>第二部分：数字孪生与仿真的区别（10分钟）</strong></p><ol><li>仿真是离线的：建模型→输入参数→运行→得到结果→模型停了</li><li>数字孪生是在线的：和物理实体之间有持续数据通道，物理世界变了数字世界跟着变，数字世界的决策可以反向控制物理世界</li><li>类比：仿真是&quot;拍一张照片分析&quot;，数字孪生是&quot;装了一面实时镜子&quot;</li><li><strong>教学提示</strong>：这是学生容易混淆的概念，务必用类比讲透。可以让学生回忆第6章的Dashboard——Dashboard是&quot;数据仪表盘&quot;，数字孪生是&quot;沉浸式3D场景&quot;，两者有本质联系但层次不同</li></ol><p><strong>第三部分：三个递进的层次（15分钟）</strong></p><ol><li><strong>以虚映实</strong>：物理工厂的实时状态被镜像到数字空间。比第6章的Dashboard更进一步——Dashboard是&quot;数据仪表盘&quot;，数字孪生是&quot;沉浸式3D场景&quot;</li><li><strong>以虚控实</strong>：数字空间下达的指令可以反向控制物理设备。需要传感器到执行器的双向数据通道——第3章的通信协议和第4章的边缘网关正是基础</li><li><strong>以虚优实</strong>：在数字孪生里做实验，试错成本为零，试对了再改物理世界。这是&quot;边缘执行→云端训练→模型下发&quot;正反馈循环的孪生版本</li><li><strong>融合视角</strong>：数字孪生不是独立技术，而是前七章几乎所有技术的融合产物——第3章通信协议传数据、第4章边缘计算做预处理、第5章平台存储和运行模型、第6章Dashboard是最轻量的数字孪生形态</li></ol><h4 id="回顾讨论-10分钟-1" tabindex="-1">回顾讨论（10分钟） <a class="header-anchor" href="#回顾讨论-10分钟-1" aria-label="Permalink to &quot;回顾讨论（10分钟）&quot;">​</a></h4><ul><li>讨论题1：&quot;数字孪生和仿真的本质区别是什么？为什么&#39;在线联动&#39;比&#39;离线模拟&#39;更有价值？&quot;</li><li>讨论题2：&quot;从&#39;以虚映实&#39;到&#39;以虚控实&#39;再到&#39;以虚优实&#39;，每一步需要前几章的哪些技术支撑？&quot;</li><li>讨论题3：&quot;你在第6章做的Dashboard算不算数字孪生？它属于哪个层次？&quot;</li></ul><h4 id="常见q-a-2" tabindex="-1">常见Q&amp;A <a class="header-anchor" href="#常见q-a-2" aria-label="Permalink to &quot;常见Q&amp;A&quot;">​</a></h4><ul><li><p><strong>Q：数字孪生是不是就是3D可视化？</strong> A：不是。3D可视化只是数字孪生的&quot;外壳&quot;，核心是物理实体与数字模型之间的实时数据联动。没有数据驱动的3D模型只是&quot;好看的动画&quot;，不是数字孪生。</p></li><li><p><strong>Q：仿真就没有价值了吗？</strong> A：仿真仍然非常有价值。在产品设计阶段（还没有物理实体），仿真是唯一的验证手段。数字孪生是仿真在&quot;有了物理实体之后&quot;的升级——从离线变在线，从单向变双向。两者是互补关系。</p></li><li><p><strong>Q：建一个数字孪生系统需要多少钱？</strong> A：成本差异极大。最简单的&quot;以虚映实&quot;层次（类似增强版Dashboard）可能几万到几十万；完整的&quot;以虚优实&quot;系统（3D建模+实时数据+仿真优化）可能需要数百万甚至更多。建议从最简单的层次起步，逐步升级。</p></li></ul><hr><h3 id="_8-4-区块链与工业可信互联-理论-与8-5共2课时" tabindex="-1">8.4 区块链与工业可信互联（理论，与8.5共2课时） <a class="header-anchor" href="#_8-4-区块链与工业可信互联-理论-与8-5共2课时" aria-label="Permalink to &quot;8.4 区块链与工业可信互联（理论，与8.5共2课时）&quot;">​</a></h3><h4 id="教学导入-10分钟-3" tabindex="-1">教学导入（10分钟） <a class="header-anchor" href="#教学导入-10分钟-3" aria-label="Permalink to &quot;教学导入（10分钟）&quot;">​</a></h4><ol><li><strong>提问引入</strong>：&quot;你们听说过比特币和区块链吗？区块链除了炒币还能做什么？&quot;</li><li><strong>引出主题</strong>：区块链在工业中的应用是一个需要客观看待的话题——它有理论上的应用场景，但实际落地还处于早期探索阶段</li></ol><h4 id="知识讲解-30分钟-1" tabindex="-1">知识讲解（30分钟） <a class="header-anchor" href="#知识讲解-30分钟-1" aria-label="Permalink to &quot;知识讲解（30分钟）&quot;">​</a></h4><p><strong>第一部分：区块链解决的核心问题（10分钟）</strong></p><ol><li>核心问题：在互不信任的多个参与方之间，不需要中间人担保，建立谁都无法单方面篡改的共同记录</li><li>联盟链 vs 公链：工业区块链几乎都使用联盟链——参与方需授权才能加入，共识效率远高于公链（秒级确认而非分钟级），更适合工业场景对性能的要求</li></ol><p><strong>第二部分：两个主要应用方向（10分钟）</strong></p><ol><li><strong>供应链追溯</strong>：从矿山到冶炼厂到零件加工到总装，某批特殊合金的每一次流转都记录在链上，任何一方不能事后修改</li><li><strong>设备身份认证</strong>：回顾第4章OpenPLC实验——连上端口就能读写寄存器，怎么确保连接的&quot;设备&quot;不是攻击者伪装的？理论上可以把设备唯一身份写入区块链</li></ol><p><strong>第三部分：客观分析——为什么落地案例不多（10分钟）</strong></p><ol><li>延迟问题：控制指令要求毫秒级响应，区块链共识确认需要秒级甚至更久</li><li>需求匹配问题：大多数工业场景并不需要&quot;多方不信任&quot;的前提——工厂内部PLC、SCADA、MES之间是信任关系</li><li><strong>教学提示</strong>：这是本节最重要的教学目标——不是让学生&quot;学会区块链&quot;，而是让学生学会客观看待新技术。区块链不是和5G、AI等量齐观的核心技术，它仍处于早期探索阶段。你可以知道有这项技术以及它被尝试解决什么问题，但不需要把它当作工业互联网的核心基础设施</li></ol><h4 id="回顾讨论-10分钟-2" tabindex="-1">回顾讨论（10分钟） <a class="header-anchor" href="#回顾讨论-10分钟-2" aria-label="Permalink to &quot;回顾讨论（10分钟）&quot;">​</a></h4><ul><li>讨论题1：&quot;联盟链和公链的核心区别是什么？为什么工业场景选择联盟链？&quot;</li><li>讨论题2：&quot;区块链的&#39;不可篡改&#39;在供应链追溯中有什么价值？为什么传统数据库做不到？&quot;</li><li>讨论题3：&quot;为什么区块链在工业中的落地案例远少于5G和AI？&quot;</li></ul><h4 id="常见q-a-3" tabindex="-1">常见Q&amp;A <a class="header-anchor" href="#常见q-a-3" aria-label="Permalink to &quot;常见Q&amp;A&quot;">​</a></h4><ul><li><p><strong>Q：区块链在工业中真的有用吗？</strong> A：目前来看，区块链在工业中的实际落地案例确实不多，仍处于早期探索阶段。在供应链追溯和设备身份认证方面有理论价值，但延迟、成本和需求匹配上仍有明显局限。学生应该客观认识这一点——知道有这项技术，了解它被尝试解决什么问题，但不要把它和5G、AI等量齐观。</p></li><li><p><strong>Q：联盟链和传统数据库有什么区别？</strong> A：核心区别在于&quot;信任模型&quot;。传统数据库由单一机构管理，该机构可以随时修改数据；联盟链由多个参与方共同维护，任何一方都无法单方面篡改已确认的记录。如果你的场景中所有参与方之间本来就有信任关系（如工厂内部系统），传统数据库就够用了；只有在&quot;多方不信任&quot;的场景中，联盟链才有独特价值。</p></li><li><p><strong>Q：区块链会不会在未来成为工业互联网的核心技术？</strong> A：目前无法确定。技术发展需要看实际需求驱动和成本效益比。5G和AI之所以能快速落地，是因为它们解决了工业中真实存在的痛点（无线替代有线、机器替代人眼）。区块链要成为核心技术，需要找到类似的&quot;刚需&quot;场景。保持关注，但不必过度期待。</p></li></ul><hr><h3 id="_8-5-工业安全-永远的底线-理论-与8-4共2课时" tabindex="-1">8.5 工业安全：永远的底线（理论，与8.4共2课时） <a class="header-anchor" href="#_8-5-工业安全-永远的底线-理论-与8-4共2课时" aria-label="Permalink to &quot;8.5 工业安全：永远的底线（理论，与8.4共2课时）&quot;">​</a></h3><h4 id="教学导入-10分钟-4" tabindex="-1">教学导入（10分钟） <a class="header-anchor" href="#教学导入-10分钟-4" aria-label="Permalink to &quot;教学导入（10分钟）&quot;">​</a></h4><ol><li><strong>对比提问</strong>：&quot;消费互联网出问题，可能是账号被盗、隐私泄露；工业互联网出问题，会怎样？&quot;</li><li><strong>案例引入</strong>：简要介绍一个工业网络安全事件（如乌克兰电网攻击、WannaCry对工业系统的影响），让学生感受工业安全的严重性</li><li><strong>引出主题</strong>：工业互联网安全不同于消费互联网安全——出问题可能是生产线停转、设备损毁、甚至人员伤亡</li></ol><h4 id="知识讲解-25分钟" tabindex="-1">知识讲解（25分钟） <a class="header-anchor" href="#知识讲解-25分钟" aria-label="Permalink to &quot;知识讲解（25分钟）&quot;">​</a></h4><ol><li><strong>纵深防御五层原则</strong>：逐一讲解物理隔离、访问控制、数据加密、安全审计、应急响应</li><li><strong>与前面章节的关联</strong>： <ul><li>第3章的VPN和防火墙 → 物理隔离和访问控制的实现手段</li><li>第4章的OpenPLC实验 → 如果连接的是真实设备，需要做哪些安全防护？</li><li>第7章的MQTT → 数据传输加密的重要性</li></ul></li><li><strong>课程思政</strong>：工业安全是底线，工程师要对工厂、工人、社会负责</li></ol><h4 id="回顾讨论-10分钟-3" tabindex="-1">回顾讨论（10分钟） <a class="header-anchor" href="#回顾讨论-10分钟-3" aria-label="Permalink to &quot;回顾讨论（10分钟）&quot;">​</a></h4><ul><li>讨论题1：&quot;&#39;纵深防御&#39;的五层原则中，哪一层你觉得最难做到？为什么？&quot;</li><li>讨论题2：&quot;第4章你做过OpenPLC实验——当时有没有考虑过安全问题？如果那台PLC连接的是真实的工厂设备，你需要做哪些安全防护？&quot;</li></ul><h4 id="常见q-a-4" tabindex="-1">常见Q&amp;A <a class="header-anchor" href="#常见q-a-4" aria-label="Permalink to &quot;常见Q&amp;A&quot;">​</a></h4><ul><li><p><strong>Q：物理隔离是不是最安全的？为什么还要其他层？</strong> A：物理隔离确实是最有效的安全手段之一，但现实中完全物理隔离越来越难做到——设备需要远程维护、数据需要上传分析、供应商需要远程诊断。纵深防御的思路是&quot;不要把鸡蛋放在一个篮子里&quot;，即使某一层被突破，其他层仍然能提供保护。</p></li><li><p><strong>Q：工业安全和个人有什么关系？</strong> A：工业安全事故可能造成人员伤亡、环境污染、社会影响。作为未来的工业互联网工程师，你的一个安全疏忽可能影响整条产线甚至整个工厂。安全意识不是&quot;加分项&quot;，而是&quot;必须项&quot;。</p></li></ul><hr><h3 id="_8-6-动手实践-ai辅助编程入门-实践-4课时" tabindex="-1">8.6 动手实践：AI辅助编程入门（实践，4课时） <a class="header-anchor" href="#_8-6-动手实践-ai辅助编程入门-实践-4课时" aria-label="Permalink to &quot;8.6 动手实践：AI辅助编程入门（实践，4课时）&quot;">​</a></h3><h4 id="教学导入-10分钟-5" tabindex="-1">教学导入（10分钟） <a class="header-anchor" href="#教学导入-10分钟-5" aria-label="Permalink to &quot;教学导入（10分钟）&quot;">​</a></h4><ol><li><strong>回顾提问</strong>：&quot;本书的全部实践都是在Node-RED的图形界面上完成的——拖拽节点、连线、配置参数。在真实工作中，你迟早会遇到需要写代码的场景。&quot;</li><li><strong>引出主题</strong>：这一节带你认识AI辅助编程的各种方式，并亲手体验&quot;AI帮你写代码&quot;到底是什么感觉</li></ol><h4 id="知识讲解-四种ai编程工具形态-15分钟" tabindex="-1">知识讲解：四种AI编程工具形态（15分钟） <a class="header-anchor" href="#知识讲解-四种ai编程工具形态-15分钟" aria-label="Permalink to &quot;知识讲解：四种AI编程工具形态（15分钟）&quot;">​</a></h4><ol><li><strong>网页对话式</strong>：ChatGPT、Claude、DeepSeek、Kimi、通义千问——最通用、门槛最低，但和开发环境集成度不高</li><li><strong>APP交互式</strong>：上述AI服务的手机APP版本——适合快速查问题，不太适合完整项目开发</li><li><strong>AI专用IDE</strong>：Cursor、Windsurf——为AI编程重新设计的IDE，AI能读取整个项目文件夹，理解上下文后直接生成和修改代码</li><li><strong>通用IDE的AI插件</strong>：GitHub Copilot、通义千问（阿里）、Continue——在传统IDE中以扩展插件形式工作，打字时自动预测和补全。通义千问插件由阿里云开发，支持中文自然语言编程提示，非常适合工业场景</li><li><strong>教学提示</strong>：用图8-2帮助学生建立四种形态的整体认知，重点让学生理解&quot;门槛最低的网页对话&quot;和&quot;最接近真实开发的IDE插件&quot;之间的区别</li></ol><hr><h4 id="任务一-动手体验——用ai编写温度监控代码-第4次课-约70分钟" tabindex="-1">任务一：动手体验——用AI编写温度监控代码（第4次课，约70分钟） <a class="header-anchor" href="#任务一-动手体验——用ai编写温度监控代码-第4次课-约70分钟" aria-label="Permalink to &quot;任务一：动手体验——用AI编写温度监控代码（第4次课，约70分钟）&quot;">​</a></h4><p><strong>实践准备（10分钟）</strong></p><ol><li>提前准备好VS Code安装包（如网络不好）</li><li>确保学生电脑能上网（安装插件和AI服务需要）</li></ol><p><strong>方式A：网页对话（推荐首次体验，30分钟）</strong></p><ol><li>打开deepseek.com（或其他可用的AI对话服务）</li><li>输入需求：&quot;写一段JavaScript代码，读取一个包含100条温度记录的数组，计算平均值、最大值、最小值，并找出所有超过80度的异常点&quot;</li><li>AI返回代码后，复制到<code>temperature_analyzer.js</code>文件中</li><li>追问练习：&quot;帮我在代码里加上注释&quot;&quot;如果这段代码要部署在工厂的服务器上，还需要添加哪些错误处理？&quot;</li></ol><p><strong>方式B：终端AI编程——DeepSeek TUI</strong>（推荐，40分钟）</p><p>DeepSeek TUI 是一个运行在终端里的 AI 编程助手，国产开源项目，特点是直接在终端里和AI对话编程，非常适合喜欢命令行的学生。</p><ol><li><strong>分步演示</strong>： <ul><li>安装：<code>pip install deepseek-tui</code>（或详见GitHub）</li><li>启动：在终端输入 <code>deepseek</code></li><li>用自然语言让AI写代码、改文件、调试</li></ul></li><li><strong>学生操作</strong>：跟着做，教师巡视，解决安装问题</li><li><strong>引导反思</strong>：AI生成的代码你能理解吗？如果有问题，你能调试吗？</li></ol><p><strong>方式C：VS Code插件</strong>（备选，40分钟）</p><ol><li><strong>分步演示</strong>： <ul><li>安装VS Code</li><li>安装中文语言包（Ctrl+Shift+X搜索安装）</li><li>安装通义千问插件（阿里云出品，国产AI）或Continue（开源方案）</li></ul></li><li><strong>学生操作</strong>：跟着做，教师巡视，解决安装问题</li><li><strong>验证安装</strong>：新建JavaScript文件，用中文注释写需求，AI自动补全代码</li><li><strong>引导反思</strong>：AI生成的代码你能理解吗？如果有问题，你能调试吗？</li></ol><hr><h4 id="任务二-用ai生成完整的mqtt数据采集代码-第5次课-约50分钟" tabindex="-1">任务二：用AI生成完整的MQTT数据采集代码（第5次课，约50分钟） <a class="header-anchor" href="#任务二-用ai生成完整的mqtt数据采集代码-第5次课-约50分钟" aria-label="Permalink to &quot;任务二：用AI生成完整的MQTT数据采集代码（第5次课，约50分钟）&quot;">​</a></h4><p><strong>实践准备（10分钟）</strong></p><ol><li>回顾前面学的MQTT知识（第7章）</li><li>确保Mosquitto Broker已安装并运行</li></ol><p><strong>步骤1：用AI生成MQTT数据发布代码（20分钟）</strong></p><ol><li><strong>演示写需求</strong>：展示如何用自然语言描述完整需求（模拟传感器→MQTT发布→JSON格式→错误处理）</li><li><strong>学生操作</strong>：生成代码、测试发布</li><li><strong>运行测试</strong>：用<code>mosquitto_sub -t &quot;factory/sensor/data&quot;</code>订阅主题，观察是否收到数据</li></ol><p><strong>步骤2：用AI生成数据存储代码（20分钟）</strong></p><ol><li><strong>演示写需求</strong>：展示如何描述CSV存储需求</li><li><strong>学生操作</strong>：生成代码、测试存储</li><li><strong>完整流程</strong>：同时运行两个程序，观察数据是否正确发布和存储</li></ol><hr><h4 id="讨论-ai写代码-谁为后果负责-第5次课-约20分钟" tabindex="-1">讨论：AI写代码，谁为后果负责（第5次课，约20分钟） <a class="header-anchor" href="#讨论-ai写代码-谁为后果负责-第5次课-约20分钟" aria-label="Permalink to &quot;讨论：AI写代码，谁为后果负责（第5次课，约20分钟）&quot;">​</a></h4><ol><li><strong>讨论题1</strong>：&quot;AI生成的代码你能完全读懂吗？如果其中一行代码的逻辑有问题，你能发现吗？&quot;</li><li><strong>讨论题2</strong>：&quot;想象一个场景：一位不会编程的工程师用AI生成了一段&#39;判断设备是否应该紧急停机&#39;的代码，部署到了工厂。如果这段代码有Bug——在本该停机的时候没有停机——后果由谁承担？&quot;</li><li><strong>讨论题3</strong>：&quot;AI在工业软件开发中的角色应该是什么？搜索引擎的升级版、编程搭档、还是有一天替代工程师？&quot;</li></ol><p><strong>教学提示</strong>：</p><ul><li>这三个讨论题没有标准答案，目的是让学生思考AI时代的工程师责任</li><li>讨论题2是重点——引导学生认识到：使用AI工具的人必须为结果负责，不能把责任推给AI</li><li>可以结合8.2节&quot;AI的边界&quot;和8.5节&quot;工业安全&quot;进行跨节关联讨论</li><li>鼓励不同观点的碰撞，但最终要引导学生形成&quot;人负责、AI辅助&quot;的共识</li></ul><h4 id="常见q-a-5" tabindex="-1">常见Q&amp;A <a class="header-anchor" href="#常见q-a-5" aria-label="Permalink to &quot;常见Q&amp;A&quot;">​</a></h4><ul><li><p><strong>Q：AI生成的代码能直接用于生产环境吗？</strong> A：绝对不能。AI生成的代码必须经过人工审核、测试和验证后才能用于生产环境。特别是在工业场景中，代码Bug可能导致设备损毁或人员伤亡。教材中的实践是学习体验，不是生产部署。</p></li><li><p><strong>Q：我不会编程，用AI生成的代码出了问题怎么办？</strong> A：这正是讨论题2的核心——如果你不能理解AI生成的代码，就不应该把它部署到任何关键场景中。AI降低了编程的门槛，但不降低&quot;理解你在做什么&quot;的门槛。使用AI工具的前提是你至少能读懂和验证它生成的代码。</p></li><li><p><strong>Q：AI会不会取代程序员？</strong> A：AI正在改变编程的方式——从&quot;手写每一行代码&quot;变成&quot;描述需求+审核AI生成的代码&quot;。但&quot;理解需求、设计架构、验证正确性&quot;这些核心能力仍然是人的工作。AI是编程搭档，不是替代者。</p></li></ul><hr><h2 id="四、教学评价建议" tabindex="-1">四、教学评价建议 <a class="header-anchor" href="#四、教学评价建议" aria-label="Permalink to &quot;四、教学评价建议&quot;">​</a></h2><h3 id="过程性评价" tabindex="-1">过程性评价 <a class="header-anchor" href="#过程性评价" aria-label="Permalink to &quot;过程性评价&quot;">​</a></h3><table tabindex="0"><thead><tr><th>评价维度</th><th>评价方式</th><th>评价内容</th><th>权重</th></tr></thead><tbody><tr><td>课堂参与</td><td>观察记录</td><td>学生在讨论中的参与度、提问质量</td><td>15%</td></tr><tr><td>知识理解</td><td>随堂小测</td><td>5G三大模式、AI三种形态、数字孪生三层、区块链客观认知</td><td>20%</td></tr><tr><td>实践操作</td><td>实践任务评价表</td><td>VS Code安装、AI代码生成与运行、MQTT完整流程</td><td>30%</td></tr><tr><td>代码理解</td><td>口头提问</td><td>能否解释AI生成代码的主要逻辑</td><td>15%</td></tr><tr><td>伦理思考</td><td>讨论表现</td><td>&quot;谁为后果负责&quot;讨论中的思考深度</td><td>10%</td></tr><tr><td>安全意识</td><td>综合评价</td><td>对工业安全原则的理解和重视程度</td><td>10%</td></tr></tbody></table><h3 id="实践任务评价表-对应教材8-6节" tabindex="-1">实践任务评价表（对应教材8.6节） <a class="header-anchor" href="#实践任务评价表-对应教材8-6节" aria-label="Permalink to &quot;实践任务评价表（对应教材8.6节）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>评价维度</th><th>评价项</th><th>评分标准</th><th>自评(30%)</th><th>互评(30%)</th><th>师评(40%)</th></tr></thead><tbody><tr><td>环境配置</td><td>VS Code和AI编程插件安装成功</td><td>5-4-3-2-1</td><td></td><td></td><td></td></tr><tr><td>代码功能</td><td>程序能正常运行，实现需求功能</td><td>5-4-3-2-1</td><td></td><td></td><td></td></tr><tr><td>代码理解</td><td>能解释AI生成代码的主要逻辑</td><td>5-4-3-2-1</td><td></td><td></td><td></td></tr><tr><td>安全意识</td><td>理解AI代码需要人工审核，不能直接用于生产环境</td><td>5-4-3-2-1</td><td></td><td></td><td></td></tr><tr><td>创新思维</td><td>尝试添加额外功能（如数据保存到文件、异常报警）</td><td>5-4-3-2-1</td><td></td><td></td><td></td></tr></tbody></table><h3 id="终结性评价要点" tabindex="-1">终结性评价要点 <a class="header-anchor" href="#终结性评价要点" aria-label="Permalink to &quot;终结性评价要点&quot;">​</a></h3><ul><li>选择题和判断题侧重考查基本概念和辨析能力（如5G模式匹配、数字孪生与仿真的区别、区块链的客观认知）</li><li>思考题侧重考查综合应用能力（如5G模式匹配实际场景、AI边界判断、数字孪生方案设计、技术全景图绘制）</li><li>特别关注学生对&quot;区块链在工业中的真实地位&quot;的客观认识——不应夸大也不应全盘否定</li></ul><hr><h2 id="五、思政融入设计说明" tabindex="-1">五、思政融入设计说明 <a class="header-anchor" href="#五、思政融入设计说明" aria-label="Permalink to &quot;五、思政融入设计说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>融入点</th><th>结合内容</th><th>教学方法</th><th>预期效果</th></tr></thead><tbody><tr><td><strong>制造强国</strong></td><td>5G专网、云化PLC（鞍钢、芜湖美的案例）、AI质检推动工业转型升级</td><td>案例讲解（鞍钢跨厂区云化PLC、美的灯塔工厂）</td><td>培养学生的民族自豪感和使命感，树立为制造强国做贡献的理想</td></tr><tr><td><strong>网络安全法治</strong></td><td>《网络安全法》《数据安全法》，工业安全&quot;纵深防御&quot;原则</td><td>案例讨论（工业网络攻击案例）、法律解读</td><td>培养学生的法治意识，知道工业安全是底线</td></tr><tr><td><strong>工程师伦理</strong></td><td>AI的边界、最终决策应由人做、AI代码需要审核、&quot;谁为后果负责&quot;</td><td>小组讨论、案例分析（AI代码Bug导致事故的假设案例）</td><td>培养学生的职业操守，树立负责任的技术态度</td></tr><tr><td><strong>科学精神</strong></td><td>实事求是，用数据验证假设，不盲从AI，客观认识区块链</td><td>实践操作（测试AI代码）、客观分析（区块链真实落地现状）</td><td>培养学生严谨的治学态度和科学精神，学会客观看待新技术</td></tr><tr><td><strong>劳模精神</strong></td><td>工业互联网的发展离不开无数工程师和工人的辛勤付出</td><td>故事讲解（如大国工匠、工业互联网领域的劳模）</td><td>培养学生的劳动意识，尊重劳动，崇尚劳动</td></tr></tbody></table><hr><h2 id="六、思考与练习参考答案" tabindex="-1">六、思考与练习参考答案 <a class="header-anchor" href="#六、思考与练习参考答案" aria-label="Permalink to &quot;六、思考与练习参考答案&quot;">​</a></h2><h3 id="选择题" tabindex="-1">选择题 <a class="header-anchor" href="#选择题" aria-label="Permalink to &quot;选择题&quot;">​</a></h3><ol><li><strong>C</strong>（uRLLC的核心指标是延迟低于1ms，可靠性99.9999%）</li><li><strong>C</strong>（检查电路板焊点缺陷是工业AI视觉检测的典型应用）</li><li><strong>B</strong>（&quot;以虚映实&quot;指物理工厂的实时状态被镜像到数字空间）</li><li><strong>B</strong>（区块链在工业中的实际落地案例仍较少，处于早期探索阶段——这是教材明确强调的客观认知）</li><li><strong>C</strong>（AI专用IDE是为AI编程重新设计的开发环境，AI插件是在传统IDE中嵌入AI功能）</li><li><strong>B</strong>（&quot;以虚优实&quot;的核心价值是在虚拟环境中低成本试错，找到最优方案再应用到物理世界）</li><li><strong>C</strong>（RedCap填补的是eMBB和mMTC之间的中等速率、低功耗空白）</li><li><strong>C</strong>（独立专网安全性最高——基站和核心网全部自建，物理隔离）</li></ol><h3 id="判断题" tabindex="-1">判断题 <a class="header-anchor" href="#判断题" aria-label="Permalink to &quot;判断题&quot;">​</a></h3><ol><li><strong>×</strong>（eMBB是增强移动宽带，提供大带宽；百万级设备连接是mMTC的特点）</li><li><strong>√</strong>（工业AI视觉检测相比人工目检的优势：不会疲劳、检测速度快、判断标准一致）</li><li><strong>×</strong>（AI不能替代PLC执行安全保护逻辑，安全关键功能必须由硬件安全PLC或安全继电器实现）</li><li><strong>√</strong>（数字孪生的三个层次从低到高：以虚映实 → 以虚控实 → 以虚优实）</li><li><strong>×</strong>（区块链目前在工业互联网中并未大规模替代传统数据库和通信协议，仍处于早期探索阶段）</li><li><strong>√</strong>（网页对话式AI工具只需浏览器即可使用，是学习编程时门槛最低的方式）</li><li><strong>√</strong>（数字孪生和仿真的本质区别在于数字孪生是在线的、实时联动的，仿真是离线的）</li><li><strong>√</strong>（5G云化PLC的安全关键逻辑仍然必须由本地硬件安全PLC执行）</li></ol><h3 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h3><ol><li><p><strong>5G模式匹配</strong>：</p><ul><li>A. 巡检机器人实时回传4K视频 → eMBB（需要大带宽传输高清视频）</li><li>B. 300个温度传感器每30秒发一次数据 → mMTC（需要海量连接，单设备数据量小）</li><li>C. 远程操控5公里外的无人天车 → uRLLC（需要低时延、高可靠，操控指令必须实时到达）</li></ul></li><li><p><strong>AI不能做决策的场景</strong>：</p><ul><li>例如：设备急停决策、安全联锁控制、产品质量最终判定、医疗诊断等。理由：这些场景涉及人身安全、设备安全或法律责任，AI的判断可能出错且可解释性不足，必须由人做最终决策。特别是在安全关键场景中，&quot;不知道为什么&quot;比&quot;判断错了&quot;更危险。</li></ul></li><li><p><strong>数字孪生数据采集方案</strong>：</p><ul><li>需要采集的数据：主轴转速、温度、振动、电流、位置坐标、加工参数（进给速度、切削深度）等。</li><li>采集：第3章的Modbus等协议从PLC和传感器读取数据；</li><li>传输：第4章的边缘网关做数据预处理，第7章的MQTT协议将数据上传；</li><li>存储：第5章的工业互联网平台提供数据存储和模型运行环境；</li><li>展示：第6章的Dashboard可作为最轻量的数字孪生展示界面。</li></ul></li><li><p><strong>技术全景图</strong>：</p><ul><li>参考教材最后的&quot;全书回顾&quot;技术地图，学生可根据自己的理解绘制。关键是要体现&quot;数据从设备产生→经过什么处理→在什么平台存储→用什么工具分析→以什么方式呈现→被谁使用&quot;的完整链路，并将八章的关键技术串联起来。</li></ul></li></ol><hr><h2 id="七、教学反思要点" tabindex="-1">七、教学反思要点 <a class="header-anchor" href="#七、教学反思要点" aria-label="Permalink to &quot;七、教学反思要点&quot;">​</a></h2><p>课后请思考并记录：</p><ol><li>学生对5G三大模式、RedCap、5G专网的理解程度如何？云化PLC的概念是否讲透了？</li><li>学生是否理解数字孪生与仿真的本质区别？是否能把数字孪生和前七章技术关联起来？</li><li>学生对区块链的客观认知是否到位？是否出现了&quot;过度追捧&quot;或&quot;全盘否定&quot;的极端态度？</li><li>AI编程实践的效果如何？学生能顺利生成和运行代码吗？</li><li>&quot;谁为后果负责&quot;的讨论是否深入？学生是否真正理解了AI时代的工程师责任？</li><li>学生对工业安全的重要性有认识吗？是否能将安全原则与前面章节的实践关联起来？</li><li>课时安排是否合理？10课时的理论和实践比例是否合适？</li><li>有哪些内容可以进一步优化或补充？</li></ol><hr><h2 id="八、教学资源清单" tabindex="-1">八、教学资源清单 <a class="header-anchor" href="#八、教学资源清单" aria-label="Permalink to &quot;八、教学资源清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源类型</th><th>资源名称</th><th>时长/大小</th><th>对应节次</th></tr></thead><tbody><tr><td>微课视频</td><td>IIoT-V8-01 AI在工业中的应用</td><td>12分钟</td><td>8.2</td></tr><tr><td>微课视频</td><td>IIoT-V8-02 VS Code + AI编程</td><td>15分钟</td><td>8.6</td></tr><tr><td>微课视频</td><td>IIoT-V8-03 5G、数字孪生与工业安全</td><td>15分钟</td><td>8.1/8.3/8.5</td></tr><tr><td>微课视频</td><td>IIoT-V8-04 AI生成完整工业物联网代码</td><td>18分钟</td><td>8.6</td></tr><tr><td>示例代码</td><td>第8章 温度监控示例代码</td><td>几KB</td><td>8.6</td></tr><tr><td>示例代码</td><td>第8章 MQTT发布示例代码</td><td>几KB</td><td>8.6</td></tr><tr><td>示例代码</td><td>第8章 数据存储示例代码</td><td>几KB</td><td>8.6</td></tr><tr><td>拓展案例</td><td>鞍钢5G云化PLC案例</td><td>—</td><td>8.1</td></tr><tr><td>拓展案例</td><td>芜湖美的5G-A+云化PLC案例</td><td>—</td><td>8.1</td></tr><tr><td>拓展案例</td><td>华为松山湖5G专网案例</td><td>—</td><td>8.1</td></tr><tr><td>拓展案例</td><td>宁波舟山港5G龙门吊远控案例</td><td>—</td><td>8.1</td></tr><tr><td>白皮书</td><td>《5G与工业互联网融合白皮书》</td><td>—</td><td>8.1</td></tr><tr><td>白皮书</td><td>《工业互联网安全白皮书》</td><td>—</td><td>8.5</td></tr><tr><td>拓展阅读</td><td>《数字孪生：概念、技术与应用》</td><td>—</td><td>8.3</td></tr><tr><td>拓展阅读</td><td>《AI编程实战》</td><td>—</td><td>8.6</td></tr></tbody></table><hr><h2 id="九、学生常见错误预判" tabindex="-1">九、学生常见错误预判 <a class="header-anchor" href="#九、学生常见错误预判" aria-label="Permalink to &quot;九、学生常见错误预判&quot;">​</a></h2><ol><li><p><strong>混淆5G三大模式的适用场景</strong></p><ul><li>原因：三种模式的名称（eMBB/uRLLC/mMTC）较抽象，学生容易记混</li><li>解决方案：用&quot;大带宽/低时延/海量连接&quot;三个关键词替代英文缩写记忆，配合具体场景反复练习</li></ul></li><li><p><strong>认为5G可以完全替代有线</strong></p><ul><li>原因：对5G能力过度乐观，忽视安全关键场景的特殊要求</li><li>解决方案：反复强调&quot;安全关键逻辑必须由本地硬件执行&quot;，用鞍钢案例中&quot;急停回路不能云化&quot;来说明</li></ul></li><li><p><strong>混淆数字孪生和仿真</strong></p><ul><li>原因：两者表面相似，都是&quot;用计算机模拟物理世界&quot;</li><li>解决方案：用&quot;拍照片分析&quot;vs&quot;装实时镜子&quot;的类比，强调&quot;在线联动&quot;vs&quot;离线模拟&quot;的本质区别</li></ul></li><li><p><strong>对区块链过度追捧或全盘否定</strong></p><ul><li>原因：受媒体炒作影响，或听了&quot;落地案例不多&quot;后走向另一个极端</li><li>解决方案：引导学生客观分析——知道区块链能解决什么问题（多方不信任场景），也知道它为什么还没大规模落地（延迟、成本、需求匹配），培养&quot;不盲从、不盲弃&quot;的科学态度</li></ul></li><li><p><strong>AI插件安装失败</strong></p><ul><li>原因：网络问题、VS Code版本不兼容</li><li>解决方案：提前准备离线安装包，或换用其他AI插件，或改用网页对话方式</li></ul></li><li><p><strong>AI生成的代码有Bug</strong></p><ul><li>原因：需求描述不清晰、AI理解有误</li><li>解决方案：教学生如何更清晰地描述需求，如何调试AI代码，这本身就是重要的学习内容</li></ul></li><li><p><strong>MQTT连接失败</strong></p><ul><li>原因：Mosquitto未启动、地址/端口错误</li><li>解决方案：检查Mosquitto状态，确认连接参数</li></ul></li><li><p><strong>认为AI无所不能</strong></p><ul><li>原因：对AI的边界认识不足</li><li>解决方案：通过案例和讨论，反复强调AI的局限性和人的责任；结合&quot;谁为后果负责&quot;讨论深化认识</li></ul></li></ol><hr><h2 id="十、全书总结与展望" tabindex="-1">十、全书总结与展望 <a class="header-anchor" href="#十、全书总结与展望" aria-label="Permalink to &quot;十、全书总结与展望&quot;">​</a></h2><h3 id="全书总结" tabindex="-1">全书总结 <a class="header-anchor" href="#全书总结" aria-label="Permalink to &quot;全书总结&quot;">​</a></h3><p>带领学生回顾全书技术地图（教材&quot;全书回顾&quot;部分），强调&quot;从数据到决策&quot;的系统化思维，而不是孤立的知识点。特别强调第8章的定位——前八章走过的路径正是工业互联网从&quot;连接&quot;到&quot;智能&quot;的演进之路，而这条路的终点不是某一项技术的极致，而是所有技术的协同。</p><h3 id="未来展望" tabindex="-1">未来展望 <a class="header-anchor" href="#未来展望" aria-label="Permalink to &quot;未来展望&quot;">​</a></h3><p>鼓励学生继续学习更深入的内容，比如：</p><ul><li>工业数据采集与处理</li><li>工业网络与安全</li><li>机器学习在工业中的应用</li><li>数字孪生建模</li><li>工业APP开发</li><li>5G+工业互联网融合应用</li></ul><hr><p><strong>全书完</strong></p>',149)])])}const A=o(a,[["render",d]]);export{g as __pageData,A as default};
